function model(p) {
  // A pendulum whose pivot is shaken sideways at a chosen frequency. Small-angle (linear) model in dimensionless time:
  // theta'' + 2 zeta theta' + theta = a cos(r tau), tau = omega0 t, r = drive frequency / natural frequency.
  // The steady-state amplitude has a closed form; the swing itself is integrated with RK4 from rest so the ring-up shows.
  const G = 9.81;
  const L = Math.max(0.5, Math.min(2, Math.round(p.length * 10) / 10));
  const r = Math.max(0.3, Math.min(2, Math.round(p.driveRatio * 20) / 20));
  const zeta = Math.max(0.1, Math.min(0.6, Math.round(p.damping * 100) / 100));
  const a = 0.08; // drive strength in radians-equivalent; small so the small-angle model holds
  const omega0 = Math.sqrt(G / L), period = 2 * Math.PI / omega0, driveHz = r * omega0 / (2 * Math.PI);
  // Response curve: steady-state amplitude and phase lag against the frequency ratio
  const amp = rr => a / Math.sqrt((1 - rr * rr) ** 2 + (2 * zeta * rr) ** 2);
  const phase = rr => Math.atan2(2 * zeta * rr, 1 - rr * rr);
  const curve = []; for (let rr = 0.3; rr <= 2.0001; rr += 0.025) curve.push({ r: +rr.toFixed(3), amp: +amp(rr).toFixed(4), deg: +(amp(rr) * 180 / Math.PI).toFixed(2) });
  const peakR = zeta < Math.SQRT1_2 ? Math.sqrt(1 - 2 * zeta * zeta) : 0, peakAmp = peakR ? amp(peakR) : amp(0.3);
  const steady = amp(r), lag = phase(r), q = 1 / (2 * zeta);
  // Time series over the playback window, real seconds, 60 samples a second, RK4 in dimensionless time
  const duration = 24, fps = 60, h = omega0 / fps; // step in tau per frame
  const f = (tau, th, w) => [w, -2 * zeta * w - th + a * Math.cos(r * tau)];
  let th = 0, w = 0, tau = 0; const series = [];
  for (let i = 0; i <= duration * fps; i++) {
    series.push({ t: +(i / fps).toFixed(3), theta: +th.toFixed(5), drive: +(a * Math.cos(r * tau)).toFixed(5) });
    const k1 = f(tau, th, w), k2 = f(tau + h / 2, th + h / 2 * k1[0], w + h / 2 * k1[1]), k3 = f(tau + h / 2, th + h / 2 * k2[0], w + h / 2 * k2[1]), k4 = f(tau + h, th + h * k3[0], w + h * k3[1]);
    th += h / 6 * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]); w += h / 6 * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]); tau += h;
  }
  // Envelope so far: the largest swing in each natural period, which shows the ring-up toward the steady amplitude
  const perPeriod = Math.round(period * fps), envelope = [];
  for (let i = 0; i < series.length; i += perPeriod) { const seg = series.slice(i, i + perPeriod); envelope.push({ t: seg[0].t, amp: +Math.max(...seg.map(s => Math.abs(s.theta))).toFixed(4) }); }
  const lastPeriods = series.slice(-3 * perPeriod), measured = +Math.max(...lastPeriods.map(s => Math.abs(s.theta))).toFixed(4);
  const settled = Math.abs(measured - steady) / steady < 0.12;
  const ringUp = +(1 / (zeta * omega0)).toFixed(1); // time constant of the transient, seconds
  const deg = v => (v * 180 / Math.PI).toFixed(1) + '°';
  const steps = [
    { id: 'start', t: 0, title: 'Shaking the pivot at ' + r.toFixed(2) + ' × the natural frequency', note: 'The pendulum (' + L.toFixed(1) + ' m, natural period ' + period.toFixed(2) + ' s) starts at rest. The pivot is shaken by a small, steady amount; watch how big the swing gets.' },
    { id: 'ringup', t: 5, title: 'Ringing up', note: 'The swing grows for about ' + ringUp + ' s (the damping time constant) before it settles. ' + (r > 0.9 && r < 1.1 ? 'Near resonance every push arrives in step with the swing, so it keeps adding up.' : r < 0.9 ? 'Below the natural frequency the bob simply follows the pivot.' : 'Above the natural frequency the pushes arrive out of step and the swing stays small.') },
    { id: 'steady', t: 14, title: 'Steady state: ' + deg(steady) + ' at a lag of ' + Math.round(lag * 180 / Math.PI) + '°', note: 'The amplitude settles at ' + deg(steady) + '; the peak of the response curve is ' + deg(peakAmp) + ' at ' + (peakR ? peakR.toFixed(2) : '0.3') + ' × the natural frequency. Q = ' + q.toFixed(1) + '.' },
    { id: 'sowhat', t: 20, title: 'So what', note: 'Resonance is not about pushing harder; it is about pushing in time. The same holds for retries that hit a service at its recovery rhythm.' }
  ];
  const summary = 'Drive at ' + r.toFixed(2) + ' × natural, damping ' + zeta + ': steady swing ' + deg(steady) + ' (peak ' + deg(peakAmp) + ' at ' + (peakR ? peakR.toFixed(2) : '0.3') + ' ×), lag ' + Math.round(lag * 180 / Math.PI) + '°, measured ' + deg(measured) + ' after ' + duration + ' s.';
  return { L, r, zeta, a, omega0, period, driveHz, curve, peakR: +peakR.toFixed(4), peakAmp: +peakAmp.toFixed(4), steady: +steady.toFixed(4), lag: +lag.toFixed(4), q: +q.toFixed(2), series, envelope, measured, settled, ringUp, steps, duration, markers: steps.map(s => s.t), summary };
}

