function check(p) {
  const m = model(p);
  // The response curve peaks where the closed form says (r = sqrt(1 - 2 zeta^2)) when the damping is light
  const peakIdx = m.curve.reduce((b, c, i) => (c.amp > m.curve[b].amp ? i : b), 0), peakOnCurve = m.curve[peakIdx].r;
  const peakOk = m.peakR === 0 ? peakIdx === 0 : Math.abs(peakOnCurve - m.peakR) <= 0.03;
  // The steady amplitude at the chosen drive equals the curve's value there, and the integrated swing agrees with it
  // once the transient has died (when the damping time constant fits in the window)
  const near = m.curve.reduce((b, c) => (Math.abs(c.r - m.r) < Math.abs(b.r - m.r) ? c : b), m.curve[0]);
  const curveOk = Math.abs(near.amp - m.steady) / m.steady < 0.06;
  const transientDone = 3 * m.ringUp < m.duration;
  const agree = !transientDone || Math.abs(m.measured - m.steady) / m.steady < 0.12;
  // The series starts at rest and never exceeds the small-angle range the model claims
  const restOk = m.series[0].theta === 0 && m.series.length === m.duration * 60 + 1;
  const smallOk = m.series.every(s => Math.abs(s.theta) < 0.6);
  const pass = peakOk && curveOk && agree && restOk && smallOk;
  return {
    pass,
    detail: 'Response curve peaks at ' + peakOnCurve.toFixed(2) + ' × natural (closed form ' + (m.peakR || 0.3).toFixed(2) + ')' + (peakOk ? '' : ' (mismatch)') + '; steady swing ' + (m.steady * 180 / Math.PI).toFixed(1) + '° from the formula, ' + (m.measured * 180 / Math.PI).toFixed(1) + '° measured over the last three periods' +
      (transientDone ? (agree ? ', in agreement.' : ', which disagree.') : ' (transient still dying: ring-up ' + m.ringUp + ' s).') + (smallOk ? '' : ' Swing left the small-angle range.')
  };
}
